import facts from './data/facts.json';
import { isLocale, type Locale } from './i18n';

/**
 * Country facts generated by scripts/fetch-country-facts.mjs from Wikidata (CC0):
 * each country's main capital (English and Turkish names) and latest population.
 */

export type CapitalName = { en: string; tr: string };

export type CountryFacts = {
  /** The designated main capital: the only one the quiz shows. */
  capital: CapitalName;
  /** Other official capitals (e.g. La Paz for Bolivia). Listed for reference, never shown as Options. */
  also?: CapitalName[];
  population: number;
};

export const COUNTRY_FACTS: Readonly<Record<string, CountryFacts>> = facts;

function factsOf(code: string): CountryFacts | undefined {
  const key = code.toLowerCase();
  return Object.prototype.hasOwnProperty.call(COUNTRY_FACTS, key) ? COUNTRY_FACTS[key] : undefined;
}

/** The main capital's name in a Locale (English for an unknown Locale), or undefined for an unknown code. */
export function capitalOf(code: string, locale: Locale | string): string | undefined {
  const capital = factsOf(code)?.capital;
  if (!capital) return undefined;
  return isLocale(locale) ? capital[locale] : capital.en;
}

/** The latest known population, or undefined for an unknown code. */
export function populationOf(code: string): number | undefined {
  return factsOf(code)?.population;
}
